## 具體實作範例

下面以 **React + Next.js + Tailwind + Zustand** 為例，展示一個簡單的「商品列表」頁面實作流程。

### 1. 初始化 Next.js + TypeScript

```bash
npx create-next-app@latest my-ecommerce --typescript
cd my-ecommerce
npm install tailwindcss postcss autoprefixer
npx tailwindcss init -p
```

在 `tailwind.config.js` 加入：

```js
module.exports = {
  content: [
    "./pages/**/*.{js,ts,tsx}",
    "./components/**/*.{js,ts,tsx}",
  ],
  theme: {
    extend: {},
  },
  plugins: [],
}
```

在 `globals.css` 引入 Tailwind：

```css
@tailwind base;
@tailwind components;
@tailwind utilities;
```

### 2. 建立 Zustand store

```ts
// store/cartStore.ts
import create from 'zustand';

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

interface CartState {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (id: string) => void;
  clearCart: () => void;
}

export const useCartStore = create<CartState>((set) => ({
  items: [],
  addItem: (item) =>
    set((state) => {
      const existing = state.items.find((i) => i.id === item.id);
      if (existing) {
        return {
          items: state.items.map((i) =>
            i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i
          ),
        };
      }
      return { items: [...state.items, { ...item, quantity: 1 }] };
    }),
  removeItem: (id) =>
    set((state) => ({
      items: state.items.filter((i) => i.id !== id),
    })),
  clearCart: () => set({ items: [] }),
}));
```

### 3. 商品列表頁面

```tsx
// pages/index.tsx
import { GetStaticProps } from 'next';
import Image from 'next/image';
import Link from 'next/link';
import { useCartStore } from '../store/cartStore';

interface Product {
  id: string;
  name: string;
  price: number;
  image: string;
}

export default function Home({ products }: { products: Product[] }) {
  const addToCart = useCartStore((state) => state.addItem);

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-4">商品列表</h1>
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
        {products.map((p) => (
          <div key={p.id} className="border rounded shadow p-4 flex flex-col">
            <Link href={`/product/${p.id}`}>
              <a>
                <Image src={p.image} alt={p.name} width={300} height={300} />
                <h2 className="mt-2 font-semibold">{p.name}</h2>
              </a>
            </Link>
            <p className="mt-1 text-gray-700">${p.price.toFixed(2)}</p>
            <button
              onClick={() => addToCart(p)}
              className="mt-auto bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700"
            >
              加入購物車
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

// 假設你有一個 API 或 CMS，這裡用 getStaticProps 來預渲染
export const getStaticProps: GetStaticProps = async () => {
  const res = await fetch('https://api.example.com/products');
  const products: Product[] = await res.json();

  return {
    props: { products },
    revalidate: 60, // 每 60 秒重新生成一次
  };
};
```

### 4. 商品詳情頁面

```tsx
// pages/product/[id].tsx
import { GetStaticPaths, GetStaticProps } from 'next';
import Image from 'next/image';
import { useCartStore } from '../../store/cartStore';

interface Product {
  id: string;
  name: string;
  price: number;
  description: string;
  image: string;
}

export default function ProductPage({ product }: { product: Product }) {
  const addToCart = useCartStore((state) => state.addItem);

  return (
    <div className="container mx-auto p-4 flex flex-col md:flex-row gap-6">
      <div className="md:w-1/2">
        <Image src={product.image} alt={product.name} width={500} height={500} />
      </div>
      <div className="md:w-1/2">
        <h1 className="text-3xl font-bold">{product.name}</h1>
        <p className="mt-2 text-gray-700">${product.price.toFixed(2)}</p>
        <p className="mt-4">{product.description}</p>
        <button
          onClick={() => addToCart(product)}
          className="mt-6 bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700"
        >
          加入購物車
        </button>
      </div>
    </div>
  );
}

export const getStaticPaths: GetStaticPaths = async () => {
  const res = await fetch('https://api.example.com/products');
  const products: Product[] = await res.json();

  const paths = products.map((p) => ({ params: { id: p.id } }));

  return { paths, fallback: 'blocking' };
};

export const getStaticProps: GetStaticProps = async ({ params }) => {
  const res = await fetch(`https://api.example.com/products/${params?.id}`);
  const product: Product = await res.json();

  return { props: { product }, revalidate: 60 };
};
```

### 5. 購物車頁面

```tsx
// pages/cart.tsx
import { useCartStore } from '../store/cartStore';
import Link from 'next/link';

export default function Cart() {
  const { items, removeItem, clearCart } = useCartStore((state) => ({
    items: state.items,
    removeItem: state.removeItem,
    clearCart: state.clearCart,
  }));

  const total = items.reduce((sum, i) => sum + i.price * i.quantity, 0);

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-4">購物車</h1>
      {items.length === 0 ? (
        <p>購物車是空的！</p>
      ) : (
        <>
          <ul className="space-y-4">
            {items.map((i) => (
              <li key={i.id} className="flex justify-between items-center border-b pb-2">
                <span>{i.name} x {i.quantity}</span>
                <span>${(i.price * i.quantity).toFixed(2)}</span>
                <button
                  onClick={() => removeItem(i.id)}
                  className="text-red-600 hover:underline"
                >
                  移除
                </button>
              </li>
            ))}
          </ul>
          <div className="mt-4 flex justify-between items-center">
            <span className="font-semibold">總計：</span>
            <span className="text-xl font-bold">${total.toFixed(2)}</span>
          </div>
          <div className="mt-4 flex space-x-4">
            <button
              onClick={clearCart}
              className="bg-gray-600 text-white py-2 px-4 rounded hover:bg-gray-700"
            >
              清空購物車
            </button>
            <Link href="/checkout">
              <a className="bg-green-600 text-white py-2 px-4 rounded hover:bg-green-700">
                前往結帳
              </a>
            </Link>
          </div>
        </>
      )}
    </div>
  );
}
```

